-- GENERATED by `wfj generate` from data/gossip/gossip-a9.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a900ecfd3b8eafc2"] = { "Quando sentirò che hai imparato abbastanza, ti concederò la capacità di scegliere qualsiasi famiglio tu preferisca.", "." },
  ["a90690082f0b97b2"] = { "Ti prego, insegnami a diventare Fabbro di Spade, Seril.", "." },
  ["a91547ee34ba4fc5"] = { "La corruzione di un titano caduto. La corruzione del Distruttore. Dopotutto, il bastone fu forgiato dal seme dell'odio. È questo, naturalmente, ciò che mi ha portato qui...", "." },
  ["a918f042301666cb"] = { "Nella morte, gli animali del mondo ci donano sia la vita sia la protezione. Se senti di poter offrire il giusto rispetto per il loro sacrificio, allora la professione di scuoiatore potrebbe fare per te. Parla con Eladriel nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nel nord di Darnassus, per saperne di più.", "." },
  ["a91999710748e987"] = { "Elune-adore, <fratello/sorella> <mio/mia>. Qui sei <benvenuto/benvenuta>. Parla, e farò ciò che posso per aiutarti.", "." },
  ["a91ebff05a73675c"] = { "Hai visto il guardiano Backus? Così coraggioso...\n\nSecondo me è il più duro di tutti i Guardiani della Notte. Chissà se si accorge almeno che ci sono....", "." },
  ["a925f14b6eaab3c1"] = { "Ah, il vero segno del cacciatore! Braccare la propria preda nell'eterno gioco della vita. Cerca Drayl sull'⟦Hunter Rise=Altura dei Cacciatori⟧ per avere le tue risposte.", "." },
  ["a927713bac603354"] = { "Mi sa che vado fino al pozzo cento volte al giorno a prendere altra acqua. Nessun rispetto per gli anziani, te lo dico io.", "." },
  ["a933ce3e6b240080"] = { "Ti sembra che abbia il tempo o la voglia di coccolare ogni turista che entra dalla mia porta? Dimmi cosa ti serve, e fa' in fretta.", "." },
  ["a939368bdcc81cbe"] = { "Niente deve insozzare i giardini! Devi essere <distrutto/distrutta>!", "." },
  ["a93eb954414f750c"] = { "Usa la barra delle azioni del tonk, sopra la tua barra delle azioni normale, per attaccare gli altri tonk.", "." },
  ["a942e318b9d4d740"] = { "Be', il dovere chiama, no? Prima la campana... per darti vigore!", "." },
  ["a9490d47203b09db"] = { "Sei <fortunato/fortunata> ad essere <venuto/venuta> a Darnassus, dove tra i nostri istruttori puoi trovare una Cacciatrice esperta come Jocaste. Ti invito a farle visita nell'⟦Cenarion Enclave=Enclave Cenariana⟧ e a chiederle di farti da maestra.", "." },
  ["a9762d6f21215ef5"] = { "Bronzebeard è sparito di nuovo! Quel nano non ha preso proprio niente del buon senso di suo fratello.", "." },
  ["a97767997531d493"] = { "Salute, <fratello/sorella>... Vorrei un momento del tuo tempo, se posso.\n\nNoi tauren abbiamo sopportato molte prove e tribolazioni per fondare la nostra patria. Ora ci troviamo a corto di stoffa. Se hai materiali da parte, ti chiedo di donarli. Aiutandoci ti guadagneresti di certo la gratitudine dei tauren di ogni dove!", "." },
  ["a97b06ab7955d2c1"] = { "Finalmente... la morte! Maledetto Hakkar! Maledetto!", "." },
  ["a97d957783375795"] = { "Dicono che Duriel sia una feroce elfa della notte. Sarà un bel combattimento!", "." },
  ["a980b46705e5b6bb"] = { "Se il dovere non mi legasse a mastro Ravenholdt, ti seguirei fino ai confini del mondo, <signore/signora> {name}. Sei la grazia e l'astuzia fatte persona.", "." },
  ["a9847e17bf120540"] = { "Ecco la parete orientale della montagna! Ora taglio verso sud; cerca di starmi dietro. Non siamo ancora fuori pericolo!", "." },
  ["a9851cb86eaf9356"] = { "Posso insegnarti i segreti di ⟦Horse Riding=Cavalca-Cavallo⟧, se hai abbastanza oro per pagare la lezione!", "." },
  ["a98e5e3cc90adb4c"] = { "%s ringhia e si guarda intorno con aria aggressiva", "." },
  ["a98fe305aadb8e66"] = { "La macchina si gira verso di te.\n\nSul retro della macchina c'è una fessura vuota dalla forma stranamente irregolare, con un'incisione che dice: \"Propietà d'l Capitan Gelkak Gyromast\"", "." },
  ["a997ae284b0ec8ec"] = { "Devi diventare più forte, {class}, prima di poterci aiutare nella ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["a99c6a0c4ea282b9"] = { "⟦Alterac Valley=Valle d'Alterac⟧", "." },
  ["a99daa3cca98ad8a"] = { "Sì sì, lo so che a Dadanga non piace il fumo. Però, dall'odore, sembra che a Dadanga non piaccia nemmeno lavarsi.", "." },
  ["a99e092c8fcc9626"] = { "O quello è un osso di kodo di prima scelta, o è ora che mi metta gli occhialoni!", "." },
  ["a9a31527f6860c7a"] = { "Credo di aver smarrito lo stendardo che mi avevi incantato, Falrin.", "." },
  ["a9a69a2e20ab9274"] = { "Mi dispiace, <fratello/sorella>, ma non venderò i miei raptor a chi non ha dimostrato di essere almeno Amichevole con la tribù ⟦Darkspear=Lanciascura⟧. Quando ti farai valere e ci dimostrerai di essere almeno Amichevole, allora i miei raptor saranno a tua disposizione.", "." },
  ["a9aef1f838939d17"] = { "Forse un giorno il tuo contributo all'⟦Alliance=Alleanza⟧ sarà grande quanto quello degli eroi che hai visto oggi. Onorali, {name}.", "." },
  ["a9b36d68e4d56fc8"] = { "Nelle ⟦Barrens=Savane⟧ nord-orientali si trova una pozza d'acqua ammorbata dall'inquinamento. La gente del posto la chiama ⟦Sludge Fen=Palude Fangosa⟧; la ⟦Venture Company=S.P.R. & Co.⟧ ha trasformato quelle acque un tempo azzurre e cristalline in un pantano di scarti e rifiuti industriali. Nel cuore di questa palude si trova ciò che cerchi, {name}.\n\nAttenzione: la ⟦Venture Company=S.P.R. & Co.⟧ non tollera gli intrusi, e considera tale chiunque non lavori per lei. Tu sarai un bersaglio in particolare, in quanto <protettore/protettrice> della natura, qualcosa a cui si oppongono con veemenza.", "." },
  ["a9b87d301a976fc7"] = { "Drek'Thar è il capo militare e spirituale del ⟦Frostwolf Clan=Clan Lupi Bianchi⟧ ad Alterac, e guida i suoi fratelli dalla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.\n\nSe viene sconfitto, le forze dell'⟦Horde=Orda⟧ ad Alterac crolleranno.", "." },
  ["a9b9cf43457121bc"] = { "%s consegna lo Scettro delle Sabbie Mutevoli a Fandral Staghelm.", "." },
  ["a9ba3752bcbfce77"] = { "Il tempo della guerra è quasi giunto, {class}! Sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ hanno completato i preparativi. Tutto il nostro materiale bellico viene spedito a ⟦Silithus=Silitus⟧ proprio ora. Mi aspetto che l'ultima parte arrivi entro un giorno. Quando tutto sarà radunato là, chi avrà portato a termine l'arduo compito di ricomporre lo Scettro delle Sabbie Mutevoli lo batterà contro lo Scarab Gong e aprirà i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Allora si combatterà una battaglia come non se ne vedevano da secoli!\n\nLok'tar Ogar!", "." },
  ["a9bb5156e799029f"] = { "QUESTO EVENTO FUNZIONA.", "." },
  ["a9bfa3fdffe0e7f7"] = { "Signori del Terrore? Forse intendi lord Banehollow. Ti manda i suoi saluti, e ha un messaggio per te...", "." },
  ["a9bfc1fc0f5eb96f"] = { "Ho appena assegnato l'uccisione a {name}.", "." },
  ["a9c8dad921b9c6fc"] = { "Ahh, sei tornat<o/a>. Se hai la pietra, vuol dire che la montagna ti ha scelt<o/a> davvero. Ti darò il totem che ti ha promesso. Ma se sei venut<o/a> a mani vuote, fuori dai piedi! Il sentiero non è per chi dimentica la propria strada.", "." },
  ["a9cdccbbdc211915"] = { "Ora guarda...", "." },
  ["a9d0b70accade887"] = { "Qui parla Rigger Gizelton: chiedo aiuto per scortare la mia carovana oltre la ⟦Mannoroc Coven=Congrega di Mannoroc⟧. Sono sulla strada a est di Predombra.", "." },
  ["a9e283b41e728d69"] = { "Qualcuno deve averli aiutati.", "." },
  ["a9e55dec58ed20cc"] = { "Ba-a-asta! Fatelo smettere!!", "." },
  ["a9eb73c45815802c"] = { "Osannato.", "." },
  ["a9f47d4753737fc8"] = { "Seguimi e ti aprirò la porta del cortile.", "." },
  ["a9f5572bd496891e"] = { "Bravo, Gerard, hai superato te stesso, ancora una volta.", "." },
  ["a9f5993329effbaa"] = { "Che sentano l'ira dello Stormo dei Draghi Blu! Che Malygos mi protegga!", "." },
  ["a9fe35cad646d51b"] = { "Mi stavi parlando della Veiled Blade e di come hai accettato la missione sbagliata.", "." },
})
